 const artifactMarkup=(arr=[])=>`<div class="artifact-marks" aria-label="산출물 구성">${[['seeding','방향'],['planting','형태'],['growing','마감'],['blooming','발표']].map(([kind,label])=>`<span class="artifact-mark ${arr.includes(kind)?'':'off'}" data-kind="${kind}" aria-label="${label}: ${arr.includes(kind)?'있음':'확인된 파일 없음'}">${label}<span class="sr-only"> ${arr.includes(kind)?'있음':'확인된 파일 없음'}</span></span>`).join('')}</div>`;
 const toast=message=>{const el=document.createElement('div');el.className='toast-message';el.textContent=message;if(dialog.open){let feedback=dialog.querySelector('.modal-feedback');if(!feedback){feedback=document.createElement('div');feedback.className='modal-feedback';feedback.setAttribute('role','status');feedback.setAttribute('aria-live','polite');dialog.append(feedback);}feedback.replaceChildren(el);}else document.getElementById('toasts').replaceChildren(el);setTimeout(()=>el.remove(),6500);};
 const dialog=document.getElementById('site-modal');let modalCleanup;
 function modal({title,html,onMount}){if(typeof modalCleanup==='function')modalCleanup();modalCleanup=null;if(dialog.open)dialog.close();dialog.querySelector('.modal-feedback')?.remove();document.getElementById('modal-title').textContent=title;document.getElementById('modal-content').innerHTML=html;dialog.scrollTop=0;dialog.showModal();modalCleanup=onMount?.(dialog);return dialog;}
 document.getElementById('modal-close').onclick=()=>dialog.close();dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close();}});
 dialog.addEventListener('keydown',e=>{if(e.key!=='Tab')return;const items=[...dialog.querySelectorAll('a[href],button:not(:disabled),input:not(:disabled),textarea:not(:disabled),select:not(:disabled),[tabindex="0"]')].filter(x=>x.getBoundingClientRect().width>1&&x.getBoundingClientRect().height>1);const first=items[0],last=items.at(-1);if(!first)return;if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}});
