 let activeCard=null,pendingCard=null,hoverTimer=null;
 const closingTimers=new Map();
 const reducedMotion=matchMedia('(prefers-reduced-motion:reduce)');
 function clearExpandedRoom(){main.querySelectorAll('[data-expanded-room]').forEach(el=>{el.style.removeProperty('--hover-tail');el.removeAttribute('data-expanded-room');});}
 function updateExpandedRoom(card){
  clearExpandedRoom();const grid=card.closest('.baton-grid,.detail-recommendations'),surface=card.closest('.feed-surface');if(!grid)return;
  const cards=[...grid.querySelectorAll('.baton-card')],rowTop=cards.at(-1)?.offsetTop;if(card.offsetTop!==rowTop)return;
  const bounds=card.getBoundingClientRect(),footer=document.querySelector('.site-footer').getBoundingClientRect();
  const tail=Math.max(0,bounds.top+bounds.height*2+12+16-footer.top);if(!tail)return;
  const host=surface||grid;host.dataset.expandedRoom='';host.style.setProperty('--hover-tail',tail+'px');
 }
 function updateDockVisibility(){
  const dock=document.querySelector('.floating-dock');if(!dock)return;dock.hidden=document.body.dataset.route!=='home';
 }
 function cancelPendingCard(){if(hoverTimer!==null)clearTimeout(hoverTimer);hoverTimer=null;pendingCard=null;}
 function closeCard(card,forceInstant=false){
  if(!card)return;clearTimeout(closingTimers.get(card));closingTimers.delete(card);
  const instant=forceInstant||card.classList.contains('card-keyboard')||reducedMotion.matches;
  card.classList.remove('card-open');card.classList.toggle('card-closing',!instant);
  if(instant)card.classList.remove('card-keyboard');else closingTimers.set(card,setTimeout(()=>{card.classList.remove('card-closing','card-keyboard');closingTimers.delete(card);if(!activeCard)clearExpandedRoom()},680));
  if(activeCard===card){activeCard=null;if(instant)clearExpandedRoom();}
 }
 function activateCard(card,keyboard=false){
  if(!card||!card.isConnected||card.classList.contains('card-dismissed'))return;
  cancelPendingCard();if(activeCard&&activeCard!==card)closeCard(activeCard);
  clearTimeout(closingTimers.get(card));closingTimers.delete(card);card.classList.remove('card-closing');
  activeCard=card;updateExpandedRoom(card);card.classList.toggle('card-keyboard',keyboard);card.classList.add('card-open');
 }
 main.addEventListener('pointerover',event=>{
  if(!matchMedia('(hover:hover) and (pointer:fine)').matches||event.pointerType==='touch')return;
  const card=event.target.closest('.baton-card');if(!card||card.contains(event.relatedTarget))return;
  card.classList.remove('card-dismissed');if(event.target.closest('.card-bookmark')&&!card.classList.contains('card-open'))return;
  cancelPendingCard();pendingCard=card;hoverTimer=setTimeout(()=>{if(pendingCard===card&&card.matches(':hover'))activateCard(card)},120);
 });
 main.addEventListener('pointerout',event=>{
  const card=event.target.closest('.baton-card');if(!card||card.contains(event.relatedTarget))return;
  if(pendingCard===card)cancelPendingCard();if(!card.querySelector(':focus-visible'))closeCard(card);
  if(!card.contains(document.activeElement))card.classList.remove('card-dismissed');
 });
 main.addEventListener('focusin',event=>{
  const card=event.target.closest('.baton-card');if(!card||!event.target.matches(':focus-visible'))return;
  if(!card.contains(event.relatedTarget))card.classList.remove('card-dismissed');activateCard(card,true);
 });
 main.addEventListener('focusout',event=>{
  const card=event.target.closest('.baton-card');if(!card||card.contains(event.relatedTarget))return;
  if(!card.matches(':hover')){closeCard(card);card.classList.remove('card-dismissed');}
 });
 document.addEventListener('keydown',event=>{
  if(event.key!=='Escape'||dialog.open)return;cancelPendingCard();if(!activeCard)return;
  activeCard.classList.add('card-dismissed');closeCard(activeCard,true);
 });

